// ---- shared chrome -------------------------------------------------------
// Inline styles only: Gmail strips <style> blocks. Coral #e35d5d is the brand
// accent from project-overview.md §25.2.
const brand = '#e35d5d';
const site = ($('Config').first().json.AMANTRIKA_SITE_URL || 'https://amantrika.com').replace(/\/+$/, '');
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const inr = (n) => '₹' + Number(n || 0).toLocaleString('en-IN');
const stat = (label, value) => `<div style="display:inline-block;min-width:118px;margin:0 14px 14px 0;"><div style="font-size:26px;font-weight:600;color:#1f1a19;line-height:1.1;">${value}</div><div style="font-size:12px;color:#8a7d7a;text-transform:uppercase;letter-spacing:.06em;margin-top:3px;">${label}</div></div>`;
const shell = (heading, bodyHtml, ctaLabel, ctaHref, footNote) => `
<div style="margin:0;padding:24px 12px;background:#faf7f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <div style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:14px;padding:32px 28px;border:1px solid #f0e6e2;">
    <div style="font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:${brand};font-weight:600;">Amantrika</div>
    <h1 style="margin:14px 0 18px;font-size:22px;line-height:1.32;color:#1f1a19;font-weight:600;">${heading}</h1>
    <div style="font-size:15px;line-height:1.65;color:#453c3a;">${bodyHtml}</div>
    ${ctaHref ? `<div style="margin:26px 0 6px;"><a href="${ctaHref}" style="display:inline-block;background:${brand};color:#ffffff;text-decoration:none;padding:13px 26px;border-radius:9px;font-weight:600;font-size:15px;">${ctaLabel}</a></div>` : ''}
    ${footNote ? `<p style="margin:24px 0 0;font-size:13px;line-height:1.6;color:#8a7d7a;">${footNote}</p>` : ''}
  </div>
  <div style="max-width:560px;margin:16px auto 0;text-align:center;font-size:12px;color:#a29793;">
    Amantrika · digital invitations for Indian celebrations<br/>
    <a href="${site}" style="color:#a29793;">${site.replace(/^https?:\/\//, '')}</a>
  </div>
</div>`;
// No /unsubscribe route exists in the app yet, so RFC 8058's mailto form is
// used. See "Follow-ups" in n8n/README.md.
const unsub = (scope) => 'mailto:' + ($('Config').first().json.AMANTRIKA_UNSUBSCRIBE_MAILBOX || 'unsubscribe@amantrika.com')
  + '?subject=' + encodeURIComponent('unsubscribe ' + scope);
const d = $json;

const resume  = site + '/onboarding?resume=' + encodeURIComponent(d.event_id);
const preview = site + '/invite/' + encodeURIComponent(d.slug);
const name = d.owner_name;
const title = d.title && d.title.trim() ? d.title.trim() : 'your invitation';

// One object per step of the drip. Copy quotes plan names and links to /pricing
// rather than hardcoding amounts: project-overview.md §25.1 says every price in
// the spec is a placeholder, and early-bird is disabled behind PRICING_EARLY_BIRD.
const steps = {
  draft_1h: {
    subject: 'Your invitation is waiting',
    heading: 'Your invitation is waiting',
    body: `<p style="margin:0 0 14px;">Hi ${esc(name)}, you started building ${esc(title)} an hour ago and stepped away. It is saved exactly as you left it.</p>
           <p style="margin:0;">Picking it up takes a minute \u2014 the next thing is ${esc(d.next_step)}.</p>`,
    cta: 'Pick up where you left off',
  },
  draft_24h: {
    subject: `You're ${d.completion_score}% done`,
    heading: `You're ${d.completion_score}% done`,
    body: `<p style="margin:0 0 14px;">Hi ${esc(name)}, ${esc(title)} is most of the way there.</p>
           <div style="background:#faf7f5;border-radius:10px;padding:16px 18px;margin:0 0 14px;">
             <div style="height:8px;background:#efe4e0;border-radius:99px;overflow:hidden;">
               <div style="height:8px;width:${Math.max(6, Math.min(100, Number(d.completion_score)))}%;background:${brand};"></div>
             </div>
             <p style="margin:12px 0 0;font-size:14px;color:#453c3a;">Next: <strong>${esc(d.next_step)}</strong></p>
           </div>`,
    cta: 'Add ' + d.next_step,
  },
  draft_72h: {
    subject: 'Nearly there \u2014 ' + title,
    heading: 'Nearly there',
    body: `<p style="margin:0 0 14px;">Hi ${esc(name)}, ${esc(title)} is ${d.completion_score}% complete. This is what it looks like right now:</p>
           <p style="margin:0 0 14px;"><a href="${preview}" style="color:${brand};font-weight:600;">See your invitation \u2192</a></p>
           <p style="margin:0;">One more pass \u2014 ${esc(d.next_step)} \u2014 and it is ready to send.</p>`,
    cta: 'Finish and publish',
  },
  draft_7d: {
    subject: 'Still holding your invitation',
    heading: 'Still holding your invitation',
    body: `<p style="margin:0 0 14px;">Hi ${esc(name)}, ${esc(title)} is still saved.${d.days_until_event != null ? ' Your celebration is in <strong>' + d.days_until_event + ' days</strong>.' : ''}</p>
           <p style="margin:0;">Booking early costs less and gives you time to get the details right. Plans and what each one includes are on the pricing page.</p>`,
    cta: 'Finish your invitation',
  },
  draft_30d: {
    subject: 'Last note about your invitation',
    heading: 'Last note about your invitation',
    body: `<p style="margin:0 0 14px;">Hi ${esc(name)}, this is the last time we will write about ${esc(title)}. It stays saved in your account either way \u2014 nothing is deleted.</p>
           <p style="margin:0;">If the celebration is still ahead of you, it is waiting.</p>`,
    cta: 'Open my draft',
  },
};

const step = steps[d.kind];
const html = shell(step.heading, step.body, step.cta, resume,
  `You are receiving this because you started an invitation on Amantrika. <a href="${unsub('nudge')}" style="color:#8a7d7a;">Unsubscribe</a>`);

return { json: {
  dedupe_key: d.dedupe_key,
  to: d.owner_email,
  stored: {
    event_id: d.event_id, slug: d.slug, title: d.title, kind: d.kind,
    completion_score: d.completion_score, next_step: d.next_step,
    hours_idle: d.hours_idle, dedupe_key: d.dedupe_key,
    subject: step.subject,
    html,
    text: step.heading + '\n\n' + String(step.body).replace(/<[^>]+>/g, '').replace(/\n{3,}/g, '\n\n').trim()
      + '\n\n' + step.cta + ': ' + resume,
    unsubscribe: unsub('nudge'),
  },
} };

parameters.jsonBody:
={{ JSON.stringify({
  from: $('Config').first().json.AMANTRIKA_EMAIL_FROM,
  to: [ $json.recipient ],
  subject: $json.payload.subject,
  html: $json.payload.html,
  text: $json.payload.text,
  headers: $json.payload.unsubscribe
    ? { 'List-Unsubscribe': '<' + $json.payload.unsubscribe + '>',
        'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' }
    : {}
}) }}
